alter function public.set_updated_at() set search_path=public;
alter function public.is_adult(date) set search_path=public;
do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); end loop; end $$;
revoke execute on function public.handle_citafuego_new_user() from authenticated;
revoke execute on function public.refresh_profile_activation_for(uuid) from authenticated;
create policy admin_audit_trust_read on public.admin_audit_log for select to authenticated using(public.is_trust_admin((select auth.uid())));
create policy admin_roles_trust_read on public.admin_roles for select to authenticated using(public.is_trust_admin((select auth.uid())));
create policy feature_flags_auth_read on public.feature_flags for select to authenticated using(enabled=true or public.is_trust_admin((select auth.uid())));
create policy moderation_cases_trust_read on public.moderation_cases for select to authenticated using(public.is_trust_admin((select auth.uid())));
create policy moderation_events_trust_read on public.moderation_events for select to authenticated using(public.is_trust_admin((select auth.uid())));
create policy risk_signals_trust_read on public.risk_signals for select to authenticated using(public.is_trust_admin((select auth.uid())));
create policy risk_scores_trust_read on public.user_risk_scores for select to authenticated using(public.is_trust_admin((select auth.uid())));
create index if not exists admin_audit_log_admin_idx on public.admin_audit_log(admin_user_id,created_at desc);
create index if not exists admin_user_roles_role_idx on public.admin_user_roles(role_id,user_id);
create index if not exists analytics_events_user_idx on public.analytics_events(user_id,occurred_at desc);
create index if not exists appeals_sanction_idx on public.appeals(sanction_id);
create index if not exists appeals_user_idx on public.appeals(user_id,created_at desc);
create index if not exists boost_activations_user_idx on public.boost_activations(user_id,created_at desc);
create index if not exists catalog_prices_product_idx on public.catalog_prices(product_id,active);
create index if not exists conversation_members_user_idx on public.conversation_members(user_id,conversation_id);
create index if not exists date_proposals_match_idx on public.date_proposals(match_id,created_at desc);
create index if not exists date_proposals_proposed_by_idx on public.date_proposals(proposed_by,created_at desc);
create index if not exists entitlement_ledger_user_idx on public.entitlement_ledger(user_id,created_at desc);
create index if not exists message_attachments_message_idx on public.message_attachments(message_id);
create index if not exists moderation_cases_report_idx on public.moderation_cases(report_id);
create index if not exists moderation_cases_subject_idx on public.moderation_cases(subject_user_id,created_at desc);
create index if not exists profile_interests_interest_idx on public.profile_interests(interest_id,user_id);
create index if not exists purchases_product_idx on public.purchases(product_id);
create index if not exists purchases_user_idx on public.purchases(user_id,created_at desc);
create index if not exists reports_conversation_idx on public.reports(conversation_id);
create index if not exists reports_message_idx on public.reports(message_id);
create index if not exists reports_reporter_idx on public.reports(reporter_id,created_at desc);
create index if not exists risk_signals_user_idx on public.risk_signals(user_id,created_at desc);
create index if not exists subscriptions_product_idx on public.subscriptions(product_id);
